parameters.jsCode:
// Get the YouTube API response
const data = $input.first().json;

// Get videos from YouTube response
const youtubeItems = Array.isArray(data.items)
  ? data.items
  : [];

// Convert YouTube results into clean video objects
const videos = youtubeItems
  .filter(item => item?.id?.videoId)
  .map(item => {
    const videoId = item.id.videoId;
    const snippet = item.snippet || {};

    return {
      id: videoId,

      title: snippet.title || "YouTube Lesson",

      description: snippet.description || "",

      youtubeId: videoId,

      thumbnail:
        snippet.thumbnails?.high?.url ||
        snippet.thumbnails?.medium?.url ||
        snippet.thumbnails?.default?.url ||
        "",

      channel:
        snippet.channelTitle || "",

      publishedAt:
        snippet.publishedAt ||
        snippet.publishTime ||
        "",

      youtubeUrl:
        `https://www.youtube.com/watch?v=${videoId}`,
    };
  });

// Get original request from Webhook
const webhookData = $('Skillora AI Webhook').first().json;

const body = webhookData.body || {};

const course = body.course || "";
const language = body.language || "English";

// Send ONLY the clean data to Respond to Webhook
return [
  {
    json: {
      success: true,
      course: course,
      language: language,
      videos: videos,
    },
  },
];

const input = $input.first().json;

// Get AI output
let output =
  input.output ??
  input.text ??
  input.response ??
  input.content ??
  "";

// If output is already an object
if (typeof output === "object" && output !== null) {
  return [
    {
      json: {
        success: true,
        quiz: output,
      },
    },
  ];
}

// Convert to string
output = String(output).trim();

// Remove Markdown code fences if AI accidentally adds them
output = output
  .replace(/^```json\s*/i, "")
  .replace(/^```\s*/i, "")
  .replace(/\s*```$/i, "")
  .trim();

// Find JSON object if there is extra text
const firstBrace = output.indexOf("{");
const lastBrace = output.lastIndexOf("}");

if (firstBrace !== -1 && lastBrace !== -1) {
  output = output.substring(firstBrace, lastBrace + 1);
}

let quiz;

try {
  quiz = JSON.parse(output);
} catch (error) {
  return [
    {
      json: {
        success: false,
        error: "AI returned invalid JSON",
        raw: output,
      },
    },
  ];
}

// Get original request from Webhook
const webhookData = $('Skillora AI Webhook').first().json;

const course =
  webhookData.body?.course || quiz.course || "";

const language =
  webhookData.body?.language || quiz.language || "English";

return [
  {
    json: {
      success: true,
      module: "quiz",
      course,
      language,
      questions: quiz.questions || [],
    },
  },
];

